WITH with_last AS (SELECT s.*, top1.inventory_quantity, top1.last_restock FROM stores s LEFT JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock FROM inventory c WHERE c.store_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT city, SIZE(COLLECT_SET(city)) AS num_cities, ROUND(SUM(inventory_quantity) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS inventory_quantity_per_london, COUNT(*) AS num_rows, AVG(inventory_quantity) AS avg_inventory_quantity, APPROX_PERCENTILE(inventory_quantity, 0.9) AS inventory_quantity_p90 FROM with_last GROUP BY 1 HAVING AVG(inventory_quantity) < 1000000 ORDER BY num_rows NULLS FIRST
